(7000382, 1058369, 114285, '<td valign="top">first one I looked at, and you didn''t meet the challenge criteria to title the photo ''falling apart'', great scene though.</td>', 'first one I looked at, and you didn''t meet the challenge criteria to title the photo ''falling apart'', great scene though.', '2013-03-15 00:07:06.000000', NULL, 1),
