(7000982, 1058589, 159525, '<td valign="top">This is a beautiful scene.  I love how green the grass is.   The only thing that bothers me a little is that the main subject the barn is too centered.  A new crop would make a difference.</td>', 'This is a beautiful scene.  I love how green the grass is.   The only thing that bothers me a little is that the main subject the barn is too centered.  A new crop would make a difference.', '2013-03-15 17:44:49.000000', NULL, 1),
(7000983, 1058568, 159525, '<td valign="top">Very pretty!</td>', 'Very pretty!', '2013-03-15 17:45:06.000000', NULL, 1),
(7000984, 1057297, 159525, '<td valign="top">I like the tone of the image, and I like that the boards are leading my eyes to the figure.</td>', 'I like the tone of the image, and I like that the boards are leading my eyes to the figure.', '2013-03-15 17:46:17.000000', NULL, 1),
(7000985, 1058482, 159525, '<td valign="top">Cool looking image, but this comes across as if the dishes are broken because they were dropped.  I''m not feeling the emotional connection.</td>', 'Cool looking image, but this comes across as if the dishes are broken because they were dropped.  I''m not feeling the emotional connection.', '2013-03-15 17:48:06.000000', NULL, 1),
(7000987, 1058591, 159525, '<td valign="top">I''m not sure I''m seeing your point!  Although this is an old building the windows don''t look that old.  I find that I''m drawn to the murals on the wall so I don''t really see the falling apart.</td>', 'I''m not sure I''m seeing your point!  Although this is an old building the windows don''t look that old.  I find that I''m drawn to the murals on the wall so I don''t really see the falling apart.', '2013-03-15 17:51:47.000000', NULL, 1),
(7000988, 1058475, 159525, '<td valign="top">This comes across like the cup broke because of the heat!</td>', 'This comes across like the cup broke because of the heat!', '2013-03-15 17:53:30.000000', NULL, 1),
(7000991, 1057188, 159525, '<td valign="top">I would like to see more of the falling apart!</td>', 'I would like to see more of the falling apart!', '2013-03-15 17:56:46.000000', NULL, 1),
(7000993, 1058577, 159525, '<td valign="top">Looks like she is waiting for the bird to fall from the sky so she can catch it!  I do like the mood you created with the processing.</td>', 'Looks like she is waiting for the bird to fall from the sky so she can catch it!  I do like the mood you created with the processing.', '2013-03-15 17:57:34.000000', NULL, 1),
(7000994, 1057528, 159525, '<td valign="top">I see falling, but not the apart part.</td>', 'I see falling, but not the apart part.', '2013-03-15 17:57:57.000000', NULL, 1),
(7000995, 1058555, 136989, '<td valign="top">Wow!  Very emotional and dramatic.  I love the super-imposed image.  Nice choice on the color too ... straight b/w would have been too stark.  This conveys emotion.</td>', 'Wow!  Very emotional and dramatic.  I love the super-imposed image.  Nice choice on the color too ... straight b/w would have been too stark.  This conveys emotion.', '2013-03-15 17:57:58.000000', NULL, 1),
(7000996, 1057865, 159525, '<td valign="top">I''m having a hard time figuring out what is going on!  It looks chaotic.</td>', 'I''m having a hard time figuring out what is going on!  It looks chaotic.', '2013-03-15 17:58:00.000000', NULL, 1),
(7000997, 1057222, 159525, '<td valign="top">I''m not getting this!  I like the image but when I look at it I see melting snow and ice.  I don''t see the falling apart.</td>', 'I''m not getting this!  I like the image but when I look at it I see melting snow and ice.  I don''t see the falling apart.', '2013-03-15 17:58:51.000000', NULL, 1),
(7000998, 1058382, 136989, '<td valign="top">Cool idea! great colors and composition.  The intensity in her eyes is terrific.</td>', 'Cool idea! great colors and composition.  The intensity in her eyes is terrific.', '2013-03-15 17:59:52.000000', NULL, 1),
(7000999, 1057350, 136989, '<td valign="top">Uh oh ... the space-time continuum is falling apart.  Very cool abstract.</td>', 'Uh oh ... the space-time continuum is falling apart.  Very cool abstract.', '2013-03-15 18:01:21.000000', NULL, 1),
(7001000, 1057265, 159525, '<td valign="top">If I have this correct I think you are taking an emotional approach to the challenge. Definitely a unique approach.</td>', 'If I have this correct I think you are taking an emotional approach to the challenge. Definitely a unique approach.', '2013-03-15 18:01:58.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7001001, 1058571, 136989, '<td valign="top">Very intense.  Great color and details.  I like that the sweatshirt was gray and not black to create a lighter border.</td>', 'Very intense.  Great color and details.  I like that the sweatshirt was gray and not black to create a lighter border.', '2013-03-15 18:02:24.000000', NULL, 1),
(7001005, 1058475, 136989, '<td valign="top">Okay that is just too cool.  Can I see the after shot where the liquid goes everywhere?</td>', 'Okay that is just too cool.  Can I see the after shot where the liquid goes everywhere?', '2013-03-15 18:03:48.000000', NULL, 1),
(7001010, 1058558, 136989, '<td valign="top">Love it! Speaks to me on so many levels, all the way down to the frown on the poor dolly''s face.  The sunbeams highlighting her are a nice touch.</td>', 'Love it! Speaks to me on so many levels, all the way down to the frown on the poor dolly''s face.  The sunbeams highlighting her are a nice touch.', '2013-03-15 18:05:16.000000', NULL, 1),
(7001012, 1058505, 136989, '<td valign="top">I am sickly fascinated by this entry ... there''s one area on the top that looks like a deranged bunny to me.  I love it.  I actually wish the line across the pic wasn''t there.  I would like to have seen the umbrella fending off all that chaotic content from the guy running through.</td>', 'I am sickly fascinated by this entry ... there''s one area on the top that looks like a deranged bunny to me.  I love it.  I actually wish the line across the pic wasn''t there.  I would like to have seen the umbrella fending off all that chaotic content from the guy running through.', '2013-03-15 18:07:29.000000', NULL, 1),
(7001014, 1058549, 136989, '<td valign="top">I like the look here but I don''t like how the pieces of the coins have overlapping portions of the design.  I wanted them to fit together like a puzzle.</td>', 'I like the look here but I don''t like how the pieces of the coins have overlapping portions of the design.  I wanted them to fit together like a puzzle.', '2013-03-15 18:08:49.000000', NULL, 1),
(7001040, 1058589, 124982, '<td valign="top">I wish the focus of the image (falling down barn) was more prominent. It''s such a small part of the image, but the most important!</td>', 'I wish the focus of the image (falling down barn) was more prominent. It''s such a small part of the image, but the most important!', '2013-03-15 18:35:47.000000', NULL, 1),
(7001042, 1058537, 124982, '<td valign="top">Exceptionally beautiful capture. can''t image how you managed to get some much in focus, and so much detail in the wings. <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=103142" rel="nofollow" target="_blank">vawendy</a>? I''m not quite feeling the link to the title though? Not voting down on it, though. Best image in challenge so far.</td>', 'Exceptionally beautiful capture. can''t image how you managed to get some much in focus, and so much detail in the wings.  vawendy? I''m not quite feeling the link to the title though? Not voting down on it, though. Best image in challenge so far.', '2013-03-15 18:37:11.000000', NULL, 1),
(7001044, 1058484, 124982, '<td valign="top">Clear winner in this challenge. Was expecting to see this disintegration effect aplenty. You pulled it off very well. And heck, +1 for Ducati :)</td>', 'Clear winner in this challenge. Was expecting to see this disintegration effect aplenty. You pulled it off very well. And heck, +1 for Ducati :)', '2013-03-15 18:39:02.000000', NULL, 1),
(7001045, 1058382, 124982, '<td valign="top">Simply beautiful model! Well processed. Top 5 in challenge so far!</td>', 'Simply beautiful model! Well processed. Top 5 in challenge so far!', '2013-03-15 18:40:02.000000', NULL, 1),
(7001072, 1057350, 16148, '<td valign="top">I really like the movement you''ve captured.</td>', 'I really like the movement you''ve captured.', '2013-03-15 19:33:29.000000', NULL, 1),
(7001074, 1058462, 16148, '<td valign="top">Powerful stuff.  For me, all color or desaturated would be stronger.</td>', 'Powerful stuff.  For me, all color or desaturated would be stronger.', '2013-03-15 19:37:09.000000', NULL, 1),
(7001093, 1058565, 63218, '<td valign="top">It fits the challenge, as if oil &amp; water were vigorously avoiding each other. The colors are creating a stressed-out palette that makes me think of headaches, bad hair &amp; other mental ''falling apart'' situations. I like the feeling of falling apart better than an image of something or other literally falling apart. Good work.</td>', 'It fits the challenge, as if oil & water were vigorously avoiding each other. The colors are creating a stressed-out palette that makes me think of headaches, bad hair & other mental ''falling apart'' situations. I like the feeling of falling apart better than an image of something or other literally falling apart. Good work.', '2013-03-15 20:28:15.000000', NULL, 1),
(7001098, 1058580, 140305, '<td valign="top">Great image but why not follow the rule on the title? May hurt your overall score which is truly unfortunate :(</td>', 'Great image but why not follow the rule on the title? May hurt your overall score which is truly unfortunate :(', '2013-03-15 20:57:16.000000', NULL, 1),
(7001099, 1057520, 140305, '<td valign="top">Very nice. I like the colors and the processing you used. Great composition as well.</td>', 'Very nice. I like the colors and the processing you used. Great composition as well.', '2013-03-15 20:58:53.000000', NULL, 1),
(7001100, 1058329, 140305, '<td valign="top">I really like the color tone and the delicate feel of this image. Very nice.</td>', 'I really like the color tone and the delicate feel of this image. Very nice.', '2013-03-15 21:00:46.000000', NULL, 1),
(7001101, 1058547, 140305, '<td valign="top">Nice detail and range of tones. Nicely done.</td>', 'Nice detail and range of tones. Nicely done.', '2013-03-15 21:03:25.000000', NULL, 1),
(7001104, 1058568, 140305, '<td valign="top">One of my favourites, delicate, great colors, love the background.</td>', 'One of my favourites, delicate, great colors, love the background.', '2013-03-15 21:07:07.000000', NULL, 1),
(7001108, 1058484, 140305, '<td valign="top">Nice! Creative image and I think the colors work really well.</td>', 'Nice! Creative image and I think the colors work really well.', '2013-03-15 21:10:01.000000', NULL, 1),
(7001109, 1058379, 140305, '<td valign="top">Nice use of texture. Talk about a leaky boat :)</td>', 'Nice use of texture. Talk about a leaky boat :)', '2013-03-15 21:12:19.000000', NULL, 1),
(7001110, 1058580, 86447, '<td valign="top">The image is very well done!  Good idea to go BW to make it easier on yourself.<br/> <br/>Not such a good idea to disobey the naming rules...  I fear you''ll be dinged on the score.  <br/> <br/>(Commenting only)</td>', 'The image is very well done!  Good idea to go BW to make it easier on yourself. Not such a good idea to disobey the naming rules...  I fear you''ll be dinged on the score.   (Commenting only)', '2013-03-15 21:13:33.000000', NULL, 1),
(7001112, 1058562, 140305, '<td valign="top">Interesting concept and nicely executed.</td>', 'Interesting concept and nicely executed.', '2013-03-15 21:14:02.000000', NULL, 1),
(7001113, 1058551, 86447, '<td valign="top">Not sure what the voters will do with your title since it''s not properly titled... I like the geese.<br/> <br/>It''s an interesting image.<br/> <br/> <br/>(Commenting only)</td>', 'Not sure what the voters will do with your title since it''s not properly titled... I like the geese. It''s an interesting image.  (Commenting only)', '2013-03-15 21:14:09.000000', NULL, 1),
(7001114, 1058595, 86447, '<td valign="top">Oops!   It''s so hard to remember to change the title after uploading.  I hope the voters are kind to you.<br/> <br/> <br/>(Commenting only)</td>', 'Oops!   It''s so hard to remember to change the title after uploading.  I hope the voters are kind to you.  (Commenting only)', '2013-03-15 21:14:23.000000', NULL, 1),
(7001115, 1058544, 86447, '<td valign="top">I don''t think the extra words in the title were worth the DNMC of the challenge rule.  I hope the voters are kind to you. <br/> <br/>I like the image, but wish that blue part had been either removed or desaturated so it''s not overwhelming the wall.<br/> <br/> <br/>(Commenting only)</td>', 'I don''t think the extra words in the title were worth the DNMC of the challenge rule.  I hope the voters are kind to you.  I like the image, but wish that blue part had been either removed or desaturated so it''s not overwhelming the wall.  (Commenting only)', '2013-03-15 21:14:32.000000', NULL, 1),
(7001116, 1058369, 86447, '<td valign="top">Hmmm... I''ll be interested to see how the voters treat this since the title rule was busted.<br/> <br/>I like the image and the idea... but I wonder at why the rock is floating.  I think it would have been better without it... as if it had sunk.<br/>(Commenting only)</td>', 'Hmmm... I''ll be interested to see how the voters treat this since the title rule was busted. I like the image and the idea... but I wonder at why the rock is floating.  I think it would have been better without it... as if it had sunk.(Commenting only)', '2013-03-15 21:14:51.000000', NULL, 1),
(7001117, 1058587, 86447, '<td valign="top">What an adorable child in that nightmare!  LOL!   <br/> <br/>Not sure what the voters will think about your title being not exactly what the challenge requires.  I hope they don''t ding you for it.<br/> <br/>(Commenting only)</td>', 'What an adorable child in that nightmare!  LOL!    Not sure what the voters will think about your title being not exactly what the challenge requires.  I hope they don''t ding you for it. (Commenting only)', '2013-03-15 21:15:03.000000', NULL, 1),
(7001118, 1058560, 86447, '<td valign="top">The title is not within the rules and actually... I think the extra words limit the viewer''s view of it... or interpretation of the image.  The viewer wants to be able to come up with a story on their own, I think, and not be fed too much.   I''ve made this mistake many, many times.   *sigh*<br/> <br/>That said, I do think the USA is falling apart.  :D<br/> <br/>(Commenting only)</td>', 'The title is not within the rules and actually... I think the extra words limit the viewer''s view of it... or interpretation of the image.  The viewer wants to be able to come up with a story on their own, I think, and not be fed too much.   I''ve made this mistake many, many times.   *sigh* That said, I do think the USA is falling apart.  :D (Commenting only)', '2013-03-15 21:15:26.000000', NULL, 1),
(7001130, 1058482, 140305, '<td valign="top">Alice in Wonderland - with cool tights. Very nice.</td>', 'Alice in Wonderland - with cool tights. Very nice.', '2013-03-15 21:22:52.000000', NULL, 1),
(7001136, 1058514, 86447, '<td valign="top">You''re even handsome bald, Christophe!  Another masterpiece.<br/> <br/> <br/>(Commenting only)</td>', 'You''re even handsome bald, Christophe!  Another masterpiece.  (Commenting only)', '2013-03-15 21:27:07.000000', NULL, 1),
(7001138, 1058514, 140305, '<td valign="top">I love how one is brittle - the other fluid, struggling and falling apart in their own way. Such a creative and interesting concept. Top marks!</td>', 'I love how one is brittle - the other fluid, struggling and falling apart in their own way. Such a creative and interesting concept. Top marks!', '2013-03-15 21:33:06.000000', NULL, 1),
(7001185, 1057297, 93283, '<td valign="top">Got to admit... This shot made me laugh!!! I''m sure <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=114969" rel="nofollow" target="_blank">Gyaban</a> got a good laugh out of it too!</td>', 'Got to admit... This shot made me laugh!!! I''m sure  Gyaban got a good laugh out of it too!', '2013-03-15 22:57:47.000000', NULL, 1),
(7001200, 1058468, 141367, '<td valign="top">Ill buy that!</td>', 'Ill buy that!', '2013-03-16 00:24:11.000000', NULL, 1),
(7001201, 1058382, 141367, '<td valign="top">excellent, love this!</td>', 'excellent, love this!', '2013-03-16 00:25:35.000000', NULL, 1),
(7001202, 1058571, 141367, '<td valign="top">the color change in your face is distracting</td>', 'the color change in your face is distracting', '2013-03-16 00:27:55.000000', NULL, 1),
(7001203, 1058475, 141367, '<td valign="top">cool!</td>', 'cool!', '2013-03-16 00:28:36.000000', NULL, 1),
(7001213, 1058514, 129807, '<td valign="top">Can''t wait to read your notes on this one Christophe. Excellent work as usual. The main (and quite strong) light source seems to be coming from roughly the centre of the image behind the figures, with a secondary source from top right, so visually I don''t understand where the similarly strong light is coming from on the top figure''s chest. The column on the far left appears to be have a slightly skewed perspective and the floor appears to be going downhill towards bottom left. These are simply observations, not criticisms; you have still received the highest score I have given for this challenge. I sincerely hope you don''t mind my comments because I do admire the vast majority of your work and can only dream that I would be capable of even half as much.</td>', 'Can''t wait to read your notes on this one Christophe. Excellent work as usual. The main (and quite strong) light source seems to be coming from roughly the centre of the image behind the figures, with a secondary source from top right, so visually I don''t understand where the similarly strong light is coming from on the top figure''s chest. The column on the far left appears to be have a slightly skewed perspective and the floor appears to be going downhill towards bottom left. These are simply observations, not criticisms; you have still received the highest score I have given for this challenge. I sincerely hope you don''t mind my comments because I do admire the vast majority of your work and can only dream that I would be capable of even half as much.', '2013-03-16 04:17:36.000000', NULL, 1),
(7001251, 1058396, 135629, '<td valign="top">Front page for me, great colors!</td>', 'Front page for me, great colors!', '2013-03-16 09:39:37.000000', NULL, 1),
(7001252, 1058514, 135629, '<td valign="top">So strange, yet so awesome. Frail and empty men fighting over a last scrap of food. Well done.</td>', 'So strange, yet so awesome. Frail and empty men fighting over a last scrap of food. Well done.', '2013-03-16 09:41:47.000000', NULL, 1),
(7001253, 1058484, 135629, '<td valign="top">Super clean, very well done, really a great shot. I could see Ducati using this!</td>', 'Super clean, very well done, really a great shot. I could see Ducati using this!', '2013-03-16 09:42:32.000000', NULL, 1),
(7001254, 1057297, 135629, '<td valign="top">Love the coin-head profile, nice and comical ode to the original shot :)</td>', 'Love the coin-head profile, nice and comical ode to the original shot :)', '2013-03-16 09:43:17.000000', NULL, 1),
